INSERT INTO reference_sc_conditions (sc_id, condition_text, condition_type, axe_rule_id) VALUES
   ('1.1.1', 'Images have alternative text where required (non-decorative images).', 'axe-core', 'image-alt'),
  ('1.1.1', 'Decorative images are marked with empty alternative text (alt="") or implemented as CSS backgrounds.', 'axe-core', 'image-alt'),
  ('1.1.1', 'Linked images have descriptive and meaningful alternative text.', 'manual', NULL),
  ('1.1.1', 'Equivalent text alternatives for complex images are provided in context or via a separate linked page.', 'manual', NULL),
  ('1.1.1', 'Form buttons have descriptive values that convey their purpose.', 'manual', NULL),
  ('1.1.1', 'Inputs have appropriate accessible names.', 'axe-core', 'aria-meter-name, aria-progressbar-name, input-image-alt, role-img-alt, svg-img-alt'),
  ('1.1.1', 'Embedded multimedia is identified using accessible text alternatives.', 'axe-core', 'input-image-alt, object-alt, role-img-alt, svg-img-alt'),
  ('1.1.1', 'Frames and iframes have appropriate and descriptive titles.', 'manual', NULL),
  ('1.2.1', 'Audio-only media elements include a mechanism (such as a track or accessible reference) indicating the presence of a transcript or caption alternative.', 'axe-core', 'audio-caption  (Deprecated)'),
  ('1.2.1', 'A complete and accurate transcript is provided for all non-live audio-only content.', 'manual', NULL),
  ('1.2.1', 'The transcript includes all relevant spoken dialogue and meaningful sounds.', 'manual', NULL),
  ('1.2.1', 'For non-live video-only content, a descriptive transcript or audio description is provided.', 'manual', NULL),
  ('1.2.1', 'Decorative video-only content is correctly identified and does not require a transcript.', 'manual', NULL),
  ('1.2.1', 'Transcripts or audio descriptions are easy to locate and accessible to users.', 'manual', NULL),
  ('1.2.1', 'The transcript or audio description accurately reflects the timing and meaning of the media content.', 'manual', NULL),
  ('1.2.2', 'Prerecorded video elements include a captions track (<track kind="captions">) associated with the video.', 'axe-core', 'video-caption'),
  ('1.2.2', 'Captions are synchronized accurately with the audio.', 'manual', NULL),
  ('1.2.2', 'Captions include all spoken dialogue and relevant non-speech audio (e.g., sound effects).', 'manual', NULL),
  ('1.2.2', 'Captions are complete for the entire duration of the prerecorded video.', 'manual', NULL),
  ('1.2.3', 'A descriptive transcript or audio description is provided for non-live video.', 'manual', NULL),
  ('1.2.3', 'NOTE: Only required if there is relevant visual content that is not presented in the audio.', 'manual', NULL),
  ('1.2.4', 'Synchronized captions are provided for live media that contains audio (audio-only broadcasts, web casts, video conferences, etc.)', 'manual', NULL),
  ('1.2.5', 'Audio descriptions are provided for non-live video.', 'manual', NULL),
  ('1.2.5', 'NOTE: Only required if there is relevant visual content that is not presented in the audio.', 'manual', NULL),
  ('1.2.5', 'While not required at Level AA, for optimal accessibility WebAIM recommends descriptive transcripts in addition to audio descriptions.', 'manual', NULL),
  ('1.2.6', 'A sign language video is provided for media that contains audio', 'manual', NULL),
  ('1.2.7', 'When audio description cannot be added to video due to insufficient pauses in the audio, an alternative version of the video with pauses that allow audio descriptions is provided.', 'manual', NULL),
  ('1.2.8', 'A descriptive transcript is provided for pre-recorded media that has a video track.', 'manual', NULL),
  ('1.2.8', 'For optimal accessibility, WebAIM strongly recommends transcripts for all multimedia.', 'manual', NULL),
  ('1.2.9', 'A descriptive text transcript (e.g., the script of the live audio) is provided for live content that has audio.', 'manual', NULL),
  ('1.3.1', 'ARIA parent roles that require specific child roles contain all required child elements (for example, role="list" contains role="listitem").', 'axe-core', 'aria-required-children, aria-required-parent, list'),
  ('1.3.1', 'Headings, landmarks, lists, and other structural elements are marked up using correct native HTML semantics.', 'axe-core', 'dlitem'),
  ('1.3.1', 'Lists are implemented using appropriate HTML elements (ul, ol, dl) or correct ARIA roles where HTML is insufficient.', 'axe-core', 'list, listitem'),
  ('1.3.1', 'Tables are used only for tabular data and not for layout purposes.', 'manual', NULL),
  ('1.3.1', 'Data table headers are correctly associated with their corresponding data cells.', 'axe-core', 'th-has-data-cells'),
  ('1.3.1', 'Data tables include captions when needed and captions are correctly associated with the tables.', 'manual', NULL),
  ('1.3.1', 'Form inputs have visible and programmatically associated text labels.', 'manual', NULL),
  ('1.3.1', 'Related form controls are grouped using fieldset and legend where appropriate.', 'manual', NULL),
  ('1.3.1', 'ARIA labelling is used correctly only when native HTML semantics are insufficient.', 'manual', NULL),
  ('1.3.2', 'The reading and navigation order (determined by code order) is logical and intuitive', 'manual', NULL),
  ('1.3.3', 'Instructions do not rely upon shape, size, or visual location (e.g., "Click the square icon to continue" or "Instructions are in the right-hand column").', 'manual', NULL),
  ('1.3.3', 'Instructions do not rely upon sound (e.g., "A beeping sound indicates you may continue.")', 'manual', NULL),
  ('1.3.4', 'Orientation of web content is not restricted to only portrait or landscape, unless a specific orientation is necessary.', 'manual', NULL),
  ('1.3.5', 'Form input fields that support autocomplete use valid and appropriate autocomplete attribute values as defined by the HTML specification.', 'axe-core', 'autocomplete-valid'),
  ('1.3.5', 'The selected autocomplete values accurately reflect the intended purpose of each input field (e.g., name, email, address).', 'manual', NULL),
  ('1.3.5', 'Autocomplete attributes are applied to all relevant user data fields where applicable.', 'manual', NULL),
  ('1.3.5', 'Inputs that should not have autocomplete do not include inappropriate autocomplete values.', 'manual', NULL),
  ('1.3.6', 'Regions/landmarks are used to identify page regions.', 'manual', NULL),
  ('1.3.6', 'ARIA is used, where appropriate, to enhance HTML semantics to better identify the purpose of interface components.', 'manual', NULL),
  ('1.4.1', 'Links within blocks of text are visually distinguishable from surrounding text without relying on color alone.', 'axe-core', 'link-in-text-block'),
  ('1.4.1', 'Color is not used as the sole method to convey information, indicate status, prompt action, or distinguish visual elements other than links.', 'manual', NULL),
  ('1.4.1', 'Non-link visual cues (icons, charts, error messages, required fields, instructions) do not rely on color alone.', 'manual', NULL),
  ('1.4.1', 'The contrast ratio between link text and surrounding text is at least 3:1 when color is used to distinguish links.', 'manual', NULL),
  ('1.4.1', 'Links provide an additional visual indicator (such as underline) on hover and keyboard focus.', 'manual', NULL),
  ('1.4.1', 'Visual distinctions conveyed by color are also available programmatically or through text alternatives.', 'manual', NULL),
  ('1.4.2', 'Audio does not automatically play for more than 3 seconds without a user-controlled mechanism to stop or pause it.', 'axe-core', 'no-autoplay-audio'),
  ('1.4.2', 'A visible and operable control is available to pause, stop, or mute the audio.', 'manual', NULL),
  ('1.4.2', 'Audio controls are keyboard accessible.', 'manual', NULL),
  ('1.4.2', 'Users can independently adjust audio volume without affecting system volume.', 'manual', NULL),
  ('1.4.2', 'Audio control mechanisms are clearly labeled and understandable.', 'manual', NULL),
  ('1.4.3', 'Text and images of text meet the minimum contrast ratio of 4.5:1 for normal text.', 'axe-core', 'color-contrast'),
  ('1.4.3', 'Large-scale text meets the minimum contrast ratio of 3:1.', 'axe-core', 'color-contrast'),
  ('1.4.3', 'Text that is part of images is essential and cannot be presented using real text.', 'manual', NULL),
  ('1.4.3', 'Contrast is evaluated correctly for text rendered over gradients, images, patterns, or videos.', 'manual', NULL),
  ('1.4.3', 'Custom fonts, font weights, and font rendering do not reduce effective contrast below minimum thresholds.', 'manual', NULL),
  ('1.4.3', 'Text contrast remains sufficient in all interaction states (hover, focus, active, visited).', 'manual', NULL),
  ('1.4.3', 'Contrast is maintained when user styles, zoom, or high-contrast modes are applied.', 'manual', NULL),
  ('1.4.4', 'The viewport meta tag does not restrict user scaling (e.g., does not disable zoom or set maximum-scale less than 2).', 'axe-core', 'meta-viewport'),
  ('1.4.4', 'Text content remains readable and does not become truncated, overlapped, or clipped when zoomed to 200%.', 'manual', NULL),
  ('1.4.4', 'All functionality remains available and operable when the page is zoomed to 200%.', 'manual', NULL),
  ('1.4.4', 'Horizontal scrolling is not required for reading blocks of text at 200% zoom (except where allowed).', 'manual', NULL),
  ('1.4.4', 'Fixed-position or absolutely positioned content does not obscure text or controls when zoomed.', 'manual', NULL),
  ('1.4.4', 'Interactive elements remain visible, usable, and discoverable at 200% zoom.', 'manual', NULL),
  ('1.4.6', 'Text and images of text meet the enhanced minimum color contrast ratios of 7:1 for normal text and 4.5:1 for large or bold text based on computed foreground and background colors.', 'axe-core', 'color-contrast-enhanced'),
  ('1.4.6', 'Contrast is sufficient in all user states, including hover, focus, active, disabled, and visited states.', 'manual', NULL),
  ('1.4.6', 'Text displayed over images, gradients, patterns, or video maintains the required enhanced contrast ratios.', 'manual', NULL),
  ('1.4.6', 'Contrast remains sufficient when custom user styles, zoom, or high-contrast modes are applied.', 'manual', NULL),
  ('1.4.6', 'Images of text that contain meaningful content meet the enhanced contrast requirements.', 'manual', NULL),
  ('1.4.6', 'Dynamically updated text content maintains enhanced contrast at all times.', 'manual', NULL),
  ('1.4.6', 'Essential visual information conveyed through text is not lost due to insufficient contrast in real-world viewing conditions.', 'manual', NULL),
  ('1.4.7', 'Audio with speech has no or very low background noise so the speech is easily distinguished.', 'manual', NULL),
  ('1.4.8', 'Blocks of text over one sentence in length:', 'manual', NULL),
  ('1.4.8', 'o Are no more than 80 characters wide.', 'manual', NULL),
  ('1.4.8', 'o Are NOT fully justified (aligned to both the left and the right margins).', 'manual', NULL),
  ('1.4.8', 'o Have adequate line spacing (at least 1/2 the height of the text) and paragraph spacing (1.5 times line spacing).', 'manual', NULL),
  ('1.4.8', 'o Have defined or inherited foreground and background colors.', 'manual', NULL),
  ('1.4.8', 'o Do NOT require horizontal scrolling when the text size is doubled.', 'manual', NULL),
  ('1.4.9', 'Images that appear to contain text are programmatically detected and flagged for review.', 'axe-core', 'image-text'),
  ('1.4.9', 'Images containing text are used only for decorative purposes and do not convey essential information.', 'manual', NULL),
  ('1.4.9', 'When images of text convey information, the information cannot be presented using real text alone.', 'manual', NULL),
  ('1.4.9', 'Decorative images of text are appropriately marked so they are ignored by assistive technologies.', 'manual', NULL),
  ('1.4.9', 'Logos, branding, and other allowed exceptions are correctly identified and applied.', 'manual', NULL),
  ('1.4.10', 'No loss of content or functionality occurs, and horizontal scrolling is avoided when content is presented at a width of 320 pixels.', 'manual', NULL),
  ('1.4.10', 'o This requires responsive design for most web sites.', 'manual', NULL),
  ('1.4.10', 'This is best tested by setting the browser window to 1280 pixels wide and then zooming the page content to 400%.', 'manual', NULL),
  ('1.4.10', 'Content that requires horizontal scrolling, such as data tables, complex images (such as maps and charts), toolbars, etc. are exempted.', 'manual', NULL),
  ('1.4.11', 'A contrast ratio of at least 3:1 is present for differentiating graphical objects (such as icons and components of charts or graphs) and author-customized interface components (such as buttons, form controls, and focus indicators/outlines).', 'manual', NULL),
  ('1.4.11', 'At least 3:1 contrast is maintained in the various states (focus, hover, active, etc.) of author-customized interactive components.', 'manual', NULL),
  ('1.4.12', 'Inline styles do not set fixed line-height, letter-spacing, or word-spacing values that would prevent user text spacing adjustments.', 'axe-core', 'avoid-inline-spacing'),
  ('1.4.12', 'Content remains readable and no text is clipped, overlapped, or truncated when paragraph, line, word, and letter spacing are increased to the specified values.', 'manual', NULL),
  ('1.4.12', 'All functionality remains available and operable when text spacing is adjusted.', 'manual', NULL),
  ('1.4.12', 'Fixed heights or containers do not cause loss of content when spacing is increased.', 'manual', NULL),
  ('1.4.12', 'Text spacing adjustments do not require horizontal scrolling to read blocks of text.', 'manual', NULL),
  ('1.4.12', 'Spacing adaptations work consistently across different browsers and assistive technologies.', 'manual', NULL),
  ('1.4.13', 'When additional content is presented on hover or keyboard focus:', 'manual', NULL),
  ('1.4.13', 'o The newly revealed content can be dismissed (generally via the Esc key) without moving the pointer or keyboard focus, unless the content presents an input error or does not obscure or interfere with other page content.', 'manual', NULL),
  ('1.4.13', 'o The pointer can be moved to the new content without the content disappearing.', 'manual', NULL),
  ('1.4.13', 'o The new content must remain visible until the pointer or keyboard focus is moved away from the triggering control, the new content is dismissed, or the new content is no longer relevant.', 'manual', NULL),
  ('2.1.1', 'Scrollable regions that contain keyboard-operable content are focusable using the keyboard.', 'axe-core', 'frame-focusable-content, scrollable-region-focusable'),
  ('2.1.1', 'All interactive elements and functionality on the page can be operated using the keyboard alone.', 'axe-core', 'server-side-image-map'),
