  ('2.1.2', 'The user can navigate to and from all navigable page elements using only a keyboard.', 'manual', NULL),
  ('2.1.3', 'Scrollable regions are keyboard focusable so users can scroll and interact with the content using only the keyboard.', 'axe-core', 'scrollable-region-focusable'),
  ('2.1.3', 'All interactive functionality on the page can be operated using only the keyboard.', 'manual', NULL),
  ('2.1.3', 'Keyboard users can access and operate custom widgets and components.', 'manual', NULL),
  ('2.1.3', 'Keyboard focus order is logical and intuitive throughout the page.', 'manual', NULL),
  ('2.1.3', 'Keyboard traps are not present and users can move focus away from all components.', 'manual', NULL),
  ('2.1.3', 'All keyboard interactions work consistently across browsers and assistive technologies.', 'manual', NULL),
  ('2.1.3', 'Time-based or gesture-based interactions have equivalent keyboard alternatives.', 'manual', NULL),
  ('2.1.4', 'If a keyboard shortcut uses printable character keys, then the user must be able to disable the key command, change the defined key to a non-printable key (Ctrl, Alt, etc.), or only activate the shortcut when an associated interface component or button is focused.', 'manual', NULL),
  ('2.2.1', 'Pages do not use automatic meta refresh mechanisms that refresh or redirect the page without user control.', 'axe-core', 'meta-refresh'),
  ('2.2.1', 'Time limits imposed by scripts, sessions, or applications provide a user-controlled mechanism to turn off, adjust, or extend the time limit.', 'manual', NULL),
