  ('2.2.1', 'Time limits longer than 20 hours are correctly identified and excluded from this requirement.', 'manual', NULL),
  ('2.2.2', 'Blinking content created using deprecated HTML elements (such as <blink>) is not present.', 'axe-core', 'blink'),
  ('2.2.2', 'Automatically moving or scrolling content (e.g., carousels, sliders, marquees, animations) provides a user-controlled mechanism to pause, stop, or hide the movement.', 'manual', NULL),
  ('2.2.2', 'Automatically updating content (e.g., news tickers, live updates, chat feeds) can be paused, stopped, hidden, or controlled by the user.', 'manual', NULL),
