  ('2.2.4', 'Alerts, notifications, and updates initiated by scripts can be postponed, suppressed, or controlled by the user.', 'manual', NULL),
  ('2.2.4', 'Users are provided with clear controls to pause, stop, or delay interruptions.', 'manual', NULL),
  ('2.2.4', 'Interruptions do not occur unexpectedly or without user consent.', 'manual', NULL),
