  ('2.2.4', 'User preferences for reducing interruptions are respected.', 'manual', NULL),
  ('2.2.5', 'If an authentication session expires, the user can re-authenticate and continue the activity without losing any data from the current page.', 'manual', NULL),
  ('2.3.1', 'No page content flashes more than 3 times per second unless that flashing content is sufficiently small and the flashes are of low contrast and do not contain too much red. (See general flash and red flash thresholds)', 'manual', NULL),
  ('2.3.2', 'No page content flashes more than 3 times per second.', 'manual', NULL),
  ('2.3.3', 'Users can disable non-essential animation and movement that is triggered by user interaction', 'manual', NULL),
