  ('2.4.4', 'Links with identical text that point to different destinations are visually and programmatically distinguishable.', 'manual', NULL),
  ('2.4.4', 'Image links and image buttons convey their purpose through meaningful alternative text.', 'manual', NULL),
  ('2.4.4', 'Link purpose remains clear when links are read out of context (e.g., via a screen reader links list).', 'manual', NULL),
  ('2.4.5', 'Multiple ways are available to find other web pages on the site - at least two of: a list of related pages, table of contents, site map, site search, or list of all available web pages.', 'manual', NULL),
  ('2.4.6', 'Heading levels follow a logical and sequential order without skipping levels (e.g., h1 → h2 → h3).', 'axe-core', 'heading-order'),
